--s收到匹配结果
function UIActionBossCollectionDestoryPopupDialog:OnRegionTeamGetMatchResult(data)
    self._co = cs_coroutine.start(function()
        --成功, 准备进入歼灭战
        if checkNumber(data.result) == 0 then
            CfUtils.PlayAnimator(self.MatchNode.transform:Find("Root"), "Complete")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))

            RegionQuestMgr:GetInstance():MatchCreateRoomEntry(data, self._curSelectQuestId)
            UIModule.CloseDialog(self.controller)
        else
            CfUtils.PlayAnimator(self.MatchNode.transform:Find("Root"), "Cancel")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.333))
            GameUtils.Toast(localize("匹配失败"))
            CfUtils.SetActive(self.MatchNode, false)
        end
    end)
end

--s收到加入匹配结果
function UIActionBossCollectionDestoryPopupDialog:OnRegionTeamMatch(body)
    --成功, 可以开始匹配了
    if checkNumber(body.result) == 0 then
        self._matchTime = 60
        CfUtils.FillText(self.TextNumber, self._matchTime)
        CfUtils.SetActive(self.MatchNode, true)
        self:StartTimeDown()
    else
        CfUtils.SetActive(self.MatchNode, false)
        GameUtils.Toast(localize("加入匹配失败"))
    end
end

--开始匹配
function UIActionBossCollectionDestoryPopupDialog:OnMatch()

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectQuestId)
    if isNull(vo) then
        return
    end
    local isUnlock = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum, vo.unlockId)
    if not isUnlock then
        local err = GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum, vo.unlockId)
        GameUtils.Toast(err)
        return
    end

    RegionQuestMgr:GetInstance():StartMatchingReq({questId = self._curSelectQuestId})
end

function UIActionBossCollectionDestoryPopupDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._matchTime = self._matchTime - 1
        if self._matchTime <= 0 then
            self._matchTime = 0
            self:OnCancelMatch()
        end
        CfUtils.FillText(self.TextNumber, self._matchTime)
    end, CountDownTime, false, true)
end

function UIActionBossCollectionDestoryPopupDialog:ClearMatch()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self:OnRegionTeamMatch({result = 1})
end

--取消匹配
function UIActionBossCollectionDestoryPopupDialog:OnCancelMatch()
    RegionQuestMgr:GetInstance():CancelMatchingReq()
    self:ClearMatch()
end

function UIActionBossCollectionDestoryPopupDialog:InitData()
    self._allBossData = {}
    self._allBossData = ActionUtils.GetAllRegionAnnihilationTypeVo()

