--刷新关卡信息
function UIActionBossCollectionDestoryPopupDialog:RefreshCurPointInfo()
    local data = self._allBossData[self._curInd]
    if not data then
        return
    end
    print(table.dump(data))
    CfUtils.FillImage(self.ImgMonster, data.overviewBanner)
    print(data.overviewBanner)
    CfUtils.FillText(self.TxtName, data.name)

    self:RefreshQuests()
end

function UIActionBossCollectionDestoryPopupDialog:RefreshQuests()
    self._allQuestIds = {}
    self._curSelectQuestId = 0
    local vo = ActionUtils.GetRegionAnnihilationTypeVo(self._curBossId)
    local t = checkTable(CfUtils.Split(vo.contentLevel))
    for k, v in pairs(t) do
        if checkNumber(v) > 0 then
            table.insert(self._allQuestIds, checkNumber(v))
            if checkNumber(self._curSelectQuestId) == 0 then
                self._curSelectQuestId = checkNumber(v)
            end
        end
    end

    for k, v in pairs(self._allQuestIds) do
        local go = self.DifficultyGroup.transform:Find("Cell"..k)
        local data = QuestConfMgr:GetInstance():GetQuestVoById(v)

        self:FillQuest(go, data, k)
    end

    local childCount = self.DifficultyGroup.transform.childCount
    if #self._allQuestIds <  childCount then
        for i = #self._allQuestIds + 1, childCount do
            local go = self.DifficultyGroup.transform:Find("Cell"..i)
            CfUtils.SetActive(go, false)
        end
    end

    self:RefreshRewards()
end

function UIActionBossCollectionDestoryPopupDialog:FillQuest(go, data)
    if not go or not data then
        return
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(data.id)
    if isNull(vo) then
        return
    end
    local isUnlock = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum, vo.unlockId)
    CfUtils.SetActive(go.transform:Find("LockGroup"), not isUnlock)
    CfUtils.SetActive(go.transform:Find("NormalGroup"), isUnlock)

    CfUtils.FillText(go.transform:Find("NormalGroup/SelectGroup/TxtBattleNumber"), data.proposalLevel)

    local isCur = checkNumber(self._curSelectQuestId) == checkNumber(data.id)
    --CfUtils.SetActive(go.transform:Find("NormalGroup/SelectGroup"), isCur)
    if isCur then
        CfUtils.PlayAnimation(go, "ActionBossCollectionDestoryPopupDifficultyGroupSelectDefault")
    else
        CfUtils.PlayAnimation(go, "ActionBossCollectionDestoryPopupDifficultyGroupDefault")
    end

    SetButtonAction(go, Bind(self, self.OnBtnSelectQuest, data))
end 

function UIActionBossCollectionDestoryPopupDialog:OnBtnSelectQuest(data)
    if not data then
        return
    end

    if checkNumber(self._curSelectQuestId) > 0 then
        local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
        if ind then
            local go = self.DifficultyGroup.transform:Find("Cell"..ind)
            if go then
                --CfUtils.SetActive(go.transform:Find("SelectGroup"), false)
                CfUtils.PlayAnimation(go, "ActionBossCollectionDestoryPopupDifficultyGroupCancel")
            end 
        end
    end

    self._curSelectQuestId = checkNumber(data.id)
    if checkNumber(self._curSelectQuestId) > 0 then
        local ind = table.keyof(self._allQuestIds, checkNumber(self._curSelectQuestId))
        if ind then
            local go = self.DifficultyGroup.transform:Find("Cell"..ind)
            if go then
                --CfUtils.SetActive(go.transform:Find("SelectGroup"), true)
                CfUtils.PlayAnimation(go, "ActionBossCollectionDestoryPopupDifficultyGroupSelect")
            end 
        end
    end

    self:RefreshRewards()
end

function UIActionBossCollectionDestoryPopupDialog:RefreshRewards()
    self._allRewards = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curSelectQuestId)

    if self._isInitLoopList then
        GameUtils.ReloadData(self.ScrollView, table.count(self._allRewards))
    else
        self.ScrollView:InitListView(table.count(self._allRewards), Bind(self, self.OnRefreshIndex))
        self._isInitLoopList = true
    end
end 

function UIActionBossCollectionDestoryPopupDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self._allRewards[index + 1]

    local go = cell.gameObject
    
    CfUtils.RefeshGoodGo2(go.transform:Find("GoodNode"), data.id, data.num, nil)
    local scr = CfUtils.GetLuaScr(go.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
    if scr then
        local state = 1
        if data.type == Constants.TeamShowRewardType.RegularType then
            state = 1
        elseif data.type == Constants.TeamShowRewardType.RareType then
            state = 2
        elseif data.type == Constants.TeamShowRewardType.FristType then
            state = 3
        elseif data.type == Constants.TeamShowRewardType.StarType then
            state = 4
        elseif data.type == Constants.TeamShowRewardType.ActivityType then
            state = 5
        end
        scr:SetBonusText(RewardConfMgr:GetInstance():GetTeamShowRewardTagName(data.type), state)
    end

    return cell
end

function UIActionBossCollectionDestoryPopupDialog:GetInd(bossId)
    for k, v in pairs(self._allBossData) do
        if checkNumber(v.id) == checkNumber(bossId) then
            return k
        end
    end
    return 0
end

