end

function UIActionBossCollectionDestoryPopupDialog:RefreshArrowInfo()
    CfUtils.SetActive(self.BtnArrowLeft, self._curInd > 1)
    CfUtils.SetActive(self.BtnArrowRight, self._curInd < #self._allBossData)
end

function UIActionBossCollectionDestoryPopupDialog:OnBtnArrowLeft()
    if self._curInd <= 1 then
        return
    end
    self._curInd = self._curInd - 1
    self._curBossId = self._allBossData[self._curInd].id
    self:RefreshCurPointInfo()
    self:RefreshArrowInfo()
end

function UIActionBossCollectionDestoryPopupDialog:OnBtnArrowRight()
    if self._curInd >= #self._allBossData then
        return
    end
    self._curInd = self._curInd + 1
    self._curBossId = self._allBossData[self._curInd].id
    self:RefreshCurPointInfo()
    self:RefreshArrowInfo()
end


function UIActionBossCollectionDestoryPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._curBossId = checkNumber(argument.id)  

        self:InitData()
        
    end))
    return coWait
end

function UIActionBossCollectionDestoryPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.RegionTeamMatch, self.EventRegionTeamMatch)
        Events.RemoveListener(Constants.EventNames.RegionTeamGetMatchResult, self.EventRegionTeamGetMatchResult)

        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionBossCollectionDestoryPopupDialog
